def power(base, exponent):
    if exponent == 0:
        return 1
    if exponent == 1:
        return base
    result = 1
    base = base % exponent
    if exponent % 2 == 0:
        k = exponent // 2
        while k:
            if k & 1:
                result = result * base
            base = base * base
            k = k // 2
    else:
        k = exponent - 1
        while k:
            if k & 1:
                result = result * base
            base = base * base
            k = k // 2
    return result
